jQuery(window).on("elementor/frontend/init",function(){elementorFrontend.hooks.addAction("frontend/element_ready/form.default",function(n){var r=n.attr("data-dce-submit-on-change");if(r){var e=JSON.parse(r);if(!(!e.fields||e.fields.length===0)){var t=n.data("id");e.fields.forEach(function(i){var f=jQuery(".elementor-element-"+t+" .elementor-field-group-"+i+" input, .elementor-element-"+t+" .elementor-field-group-"+i+" select");f.on("change",function(){var d=jQuery(this).closest(".elementor-field-group"),o=d.closest(".elementor-field-type-step"),l=o.length?o.find(".elementor-field-type-next button").first():jQuery();l.length?l.trigger("click"):jQuery(this).closest("form").find(".elementor-field-type-submit button").trigger("click")})}),jQuery(".elementor-element-"+t+" .select2-selection__arrow").remove()}}})});
